const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const Module = require('node:module');
const root = process.cwd();
const web = path.join(root, 'EXTENSIONS/CVF_v1.6_AGENT_PLATFORM/cvf-web');
const ts = require(path.join(web, 'node_modules/typescript'));
const filename = path.join(web, 'src/expenses/ExpenseList.tsx');
const raw = fs.readFileSync(filename);
const sha256 = x => crypto.createHash('sha256').update(x).digest('hex');
assert.equal(sha256(raw), '801f305238f2512db663fee7ada837a7bf53a84036ea6efcd305d29985339f19');
const compiled = ts.transpileModule(raw.toString('utf8'), {compilerOptions: {module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX}});
const mod = new Module(filename, module);
mod.filename = filename;
mod.paths = Module._nodeModulePaths(path.dirname(filename));
mod._compile(compiled.outputText, filename);
const filter = mod.exports.filterExpensesByMonth;
// Independent fixture and literal expected IDs; no worker tests imported.
const rows = Object.freeze([
  ['local-last', '2026-03-31'], ['local-wrong-year', '2027-03-31'],
  ['local-impossible', '2026-03-32'], ['local-first', '2026-03-01'],
  ['local-next-month', '2026-04-01']
].map(([id, date]) => Object.freeze({id, date, label: id, amount: 1})));
const before = JSON.stringify(rows);
assert.deepEqual(filter(rows, '2026-03').map(x => x.id), ['local-last', 'local-first']);
assert.deepEqual(filter(rows, '').map(x => x.id), ['local-last', 'local-wrong-year', 'local-first', 'local-next-month']);
assert.deepEqual(filter(rows, '2026-3'), []);
assert.equal(JSON.stringify(rows), before);
const leap = [
  {id: 'century-rejected', date: '2100-02-29', label: 'a', amount: 1},
  {id: 'century-valid', date: '2400-02-29', label: 'b', amount: 1},
];
assert.deepEqual(filter(leap, '').map(x => x.id), ['century-valid']);
const report = {status: 'PASS', sourceSha256: sha256(raw), caseCount: 4,
  cases: ['independent exact March/year/calendar/order', 'blank drops impossible date', 'malformed month fails closed', 'century leap boundary'],
  inputImmutable: true, importsWorkerTests: false, providerCalls: 0};
fs.writeFileSync(path.join(__dirname, 'probe.json'), JSON.stringify(report, null, 2));
const config = ts.readConfigFile(path.join(web, 'tsconfig.json'), ts.sys.readFile);
assert.equal(config.error, undefined);
const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, web);
const options = {...parsed.options, incremental: false, noEmit: true};
const program = ts.createProgram([filename, path.join(web, 'src/expenses/ExpenseList.test.tsx')], options);
const diagnostics = ts.getPreEmitDiagnostics(program);
const typeReport = {status: diagnostics.length ? 'FAIL' : 'PASS', diagnosticCount: diagnostics.length,
  rootFiles: program.getRootFileNames().map(x => path.relative(root, x).replaceAll('\\', '/')),
  method: 'TypeScript createProgram with repository compilerOptions; exact two root files, dependencies resolved; no emit or incremental cache',
  diagnostics: ts.formatDiagnosticsWithColorAndContext(diagnostics, {getCurrentDirectory: () => web, getCanonicalFileName: x => x, getNewLine: () => '\n'})};
fs.writeFileSync(path.join(__dirname, 'types.json'), JSON.stringify(typeReport, null, 2));
console.log(JSON.stringify({probe: report, types: typeReport}));
process.exitCode = diagnostics.length ? 1 : 0;
